const complete = results.length === 6 && deepestLevel === 3;

const summary = [
  `## ${complete ? 'Complete' : 'NOT complete'}`,
  '',
  `${results.length} of 6 lanes wrote. Deepest level reached: **${deepestLevel}**.`,
  '',
  complete
    ? 'All three levels ran and their results were merged back.'
    : "A lane's write did not arrive. That is a finding — note which lane is missing from the table.",
].join('\n');

return { results, summary };
```

